const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Petén, Guatemala (approximate bounding box)
  const peten = ee.Geometry.Rectangle([-92.5, 16.0, -88.5, 17.8]);

  // Load Hansen Global Forest Change dataset
  const hansen = ee.Image('UMD/Hansen/global_forest_change_2023_v1_10');

  // Extract bands
  const treecover2000 = hansen.select('treecover2000');
  const lossyear = hansen.select('lossyear');

  // Calculate forest cover in 2001 (using 2000 baseline, assuming minimal change)
  const forestCover2001 = treecover2000;

  // Calculate cumulative loss from 2001 to 2023 (lossyear values 1-23)
  // Loss pixels have lossyear = year_since_2000 (1=2001, 23=2023)
  const cumulativeLoss2001to2023 = lossyear.gte(1).and(lossyear.lte(23)).multiply(1);

  // Count pixels with loss
  const lossPixelCount = cumulativeLoss2001to2023.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: peten,
    scale: 30,
    maxPixels: 1e9
  }).get('lossyear');

  // Count total forest pixels in 2000
  const totalForest2000 = forestCover2000.gt(0).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: peten,
    scale: 30,
    maxPixels: 1e9
  }).get('treecover2000');

  // Calculate mean forest cover percentage in 2001
  const meanCover2001 = forestCover2000.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: peten,
    scale: 30,
    maxPixels: 1e9
  }).get('treecover2000');

  // Calculate forest loss proportion
  const forestLoss2001to2023 = lossyear.gte(1).and(lossyear.lte(23)).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: peten,
    scale: 30,
    maxPixels: 1e9
  }).get('lossyear');

  // Get values
  const cover2001 = await meanCover2001.getInfo();
  const lossCount = await forestLoss2001to2023.getInfo();
  const totalForest = await totalForest2000.getInfo();

  print('=== Forest Cover Analysis: Petén, Guatemala ===');
  print(`2001 Mean Forest Cover (%): ${(cover2001 || 0).toFixed(2)}`);
  print(`Forest Loss Pixels (2001-2023): ${lossCount || 0}`);
  print(`Total Forest Pixels (2000): ${totalForest || 0}`);

  // Validation
  if (cover2001 === null || cover2001 === undefined) {
    print('C3: Invalid forest cover data');
    return 'C3';
  }

  if (lossCount === null || lossCount === 0) {
    print('C2: No valid loss pixels detected');
    return 'C2';
  }

  if (totalForest === null || totalForest === 0) {
    print('C1: No forest data available for region');
    return 'C1';
  }

  // Calculate forest cover in 2023
  const lossPercentage = (lossCount / totalForest) * 100;
  const cover2023 = cover2001 * (1 - (lossCount / totalForest));

  print(`Loss Percentage (2001-2023): ${lossPercentage.toFixed(2)}%`);
  print(`2023 Estimated Forest Cover: ${cover2023.toFixed(2)}% (relative)`);

  // Determine answer
  if (cover2023 < cover2001 && lossCount > 0) {
    print('Forest cover DECREASED from 2001 to 2023');
    print('A');
    return 'A';
  } else if (cover2023 >= cover2001) {
    print('Forest cover did NOT decrease');
    print('B');
    return 'B';
  } else {
    print('C3: Calculation inconclusive');
    return 'C3';
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
